mapper.select:
select u.user_name as userName , u.real_name as realName , u.email , u.phone , u.id_card as idCard , u.work_no as workNo , u.job_title as jobTitle, ar.create_time as createTime , u.department_id as departmentId
from t_user u LEFT JOIN t_announcement_read ar on u.id = ar.create_user
where ar.announcement_id = #{id} and  u.deleted= 0  and system_role = 1 and u.status = 1

  and  u.department_id in

    #{id}



  and ar.create_user = #{dataFilterUserId}


  and u.user_name like concat('%',#{userName},'%')


  and ar.create_department_id in

    #{item}
